import{_ as t,o as r,c as a,a as i}from"./app.c1132791.js";const d=JSON.parse('{"title":"部署","description":"","frontmatter":{},"headers":[{"level":2,"title":"GitHub Pages","slug":"github-pages","link":"#github-pages","children":[]},{"level":2,"title":"Netlify","slug":"netlify","link":"#netlify","children":[]},{"level":2,"title":"Vercel","slug":"vercel","link":"#vercel","children":[]}],"relativePath":"zh-hans/getting-started/deploy.md"}'),n={name:"zh-hans/getting-started/deploy.md"};function l(s,e,o,p,h,c){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="部署" tabindex="-1">部署 <a class="header-anchor" href="#部署" aria-hidden="true">#</a></h1><h2 id="github-pages" tabindex="-1">GitHub Pages <a class="header-anchor" href="#github-pages" aria-hidden="true">#</a></h2><p>本项目配备了自动生成部署文件的 GitHub Actions 脚本，它会在您提交修改后运行再提交到 gh-pages 分支。</p><p>需要使用时，只需要设置 GitHub Pages 的部署分支为 gh-pages 既可。</p><blockquote><p>如果您提交修改后 GitHub Actions 脚本没有自动运行，请检查您的仓库是否存在多余的其他分支，您也可以手动运行脚本。</p></blockquote><h2 id="netlify" tabindex="-1">Netlify <a class="header-anchor" href="#netlify" aria-hidden="true">#</a></h2><p>本项目为 Netlify 配备了<a href="https://github.com/importantimport/urara/blob/main/netlify.toml" target="_blank" rel="noreferrer"><strong>构建配置文件</strong></a>，当导入项目时，无需填写构建设置。</p><p>若要在 Netlify 上部署本项目，您需要拥有一个 Netlify 帐号，并在需要的仓库中安装 <a href="https://github.com/apps/netlify/installations/new" target="_blank" rel="noreferrer"><strong>Netlify app</strong></a> 后，既可访问选中的仓库。</p><p>接下来，只需要按照 <a href="https://app.netlify.com/start" target="_blank" rel="noreferrer"><strong>Import an existing project</strong></a> 页面继续操作既可完成部署过程。</p><h2 id="vercel" tabindex="-1">Vercel <a class="header-anchor" href="#vercel" aria-hidden="true">#</a></h2><p>要在 Vercel 上部署本项目，您需要拥有一个 Vercel 帐号，就可以开始<a href="https://vercel.com/new" target="_blank" rel="noreferrer"><strong>添加新项目</strong></a>。</p><p>您可以从公开 git 仓库导入项目，若要导入 GitHub 私有仓库，需关联 GitHub 帐号进行授权。</p><p>选择仓库后，Vercel 会自动识别仓库并选择合适的架构，无需填写构建与输出设置。</p><p>您还可以根据需要添加其他设置，再进行部署，最后等待部署完成既可。</p>',14)])])}const f=t(n,[["render",l]]);export{d as __pageData,f as default};
